import os

from scripts.utility.change_directory_and_delete_file import \
    change_directory_and_delete_all_input_and_output_hypergraph_files_for_binary_dataset_RF
# classic RF sklearn
from scripts.evaluation.evaluation_RF_sklearn import \
    evaluation_RF_sklearn
# RF using tree generated by minimum support sets of LAD
from scripts.evaluation.evaluation_RF_using_DTs_from_LAD import evaluation_RF_using_DTs_from_LAD


def write_single_result_for_RF_using_LAD_based_technique(dataset_name, max_depth, num_estimators, k_fold, n_repeats,
                                                         seed):
    print("Running RF sklearn....")
    avg_acc_rf, std_value_rf, avg_nodes_rf, avg_num_features_rf, avg_time_rf = evaluation_RF_sklearn(
        dataset_name=dataset_name,
        max_depth=max_depth,
        k_fold=k_fold, n_repeats=n_repeats,
        seed=seed)
    print("Running RF using DTs generated by LAD with majority votes strategy....")
    # majority votes strategy
    avg_acc_lad_majority_votes, std_value_lad_majority_votes, avg_length_subset_lad_majority_votes, avg_nodes_lad_majority_votes, avg_num_features_lad_majority_votes, avg_time_MHSes_lad_majority_votes, avg_time_subsets_ranking_lad_majority_votes, avg_time_lad_majority_votes, avg_time_rf_lad_majority_votes = evaluation_RF_using_DTs_from_LAD(
        dataset_name=dataset_name, max_depth=max_depth,
        num_estimators=num_estimators, voting_method="majority_votes", k_fold=k_fold,
        n_repeats=n_repeats, seed=seed)

    # delete all temporary files of RF using Decision tree of LAD method
    change_directory_and_delete_all_input_and_output_hypergraph_files_for_binary_dataset_RF(
        dataset_name=dataset_name,
        max_depth=max_depth)

    print("Running RF using DTs generated by LAD with soft votes strategy....")
    # soft votes strategy
    avg_acc_lad_soft_votes, std_value_lad_soft_votes, avg_length_subset_lad_soft_votes, avg_nodes_lad_soft_votes, avg_num_features_lad_soft_votes, avg_time_MHSes_lad_soft_votes, avg_time_subsets_ranking_lad_soft_votes, avg_time_lad_soft_votes, avg_time_rf_lad_soft_votes = evaluation_RF_using_DTs_from_LAD(
        dataset_name=dataset_name, max_depth=max_depth,
        num_estimators=num_estimators, voting_method="soft_votes", k_fold=k_fold,
        n_repeats=n_repeats, seed=seed)

    write_output_results_path = "output_pmmcs/" + dataset_name + "/max_depth_" + str(
        max_depth) + "/results_RF_depth_" + str(max_depth) + "_after_" + str(
        k_fold) + "_folds_and_" + str(n_repeats) + "_repeats.txt"
    with open(write_output_results_path, "w") as output_results:
        output_results.write("######################################################################\n"
                             "#                      RF sklearn summary results                          #\n"
                             "######################################################################\n")
        output_results.write("avg_test_accuracy: " + str(avg_acc_rf) + "\n")
        output_results.write("standard deviation: " + str(std_value_rf) + "\n")
        output_results.write("avg total number of nodes in a forest: " + str(avg_nodes_rf) + "\n")
        output_results.write("avg total number of features used in a forest: " + str(avg_num_features_rf) + "\n")
        output_results.write("avg_time: " + str(avg_time_rf) + "\n")
        output_results.write("######################################################################\n"
                             f"#           RF using DTs generated by LAD with majority votes       #\n"
                             "######################################################################\n")

        output_results.write("avg test accuracy: " + str(avg_acc_lad_majority_votes) + "\n")
        output_results.write("standard deviation: " + str(std_value_lad_majority_votes) + "\n")
        output_results.write("avg total number of nodes in a forest: " + str(avg_nodes_lad_majority_votes) + "\n")
        output_results.write("avg total number of features used in a forest: " + str(avg_num_features_lad_majority_votes) + "\n")
        output_results.write("avg time for rf: " + str(avg_time_rf_lad_majority_votes) + "\n\n")
        output_results.write("avg time for generating 100000 MHSes: " + str(avg_time_MHSes_lad_majority_votes) + "\n")
        output_results.write("avg time for randomly selecting LAD subsets: " + str(avg_time_subsets_ranking_lad_majority_votes) + "\n")
        output_results.write("avg time for lad: " + str(avg_time_lad_majority_votes) + "\n")
        output_results.write("avg length subset for each tree before constructing: " + str(avg_length_subset_lad_majority_votes) + "\n")

        output_results.write("######################################################################\n"
                             f"#           RF using DTs generated by LAD with soft votes           #\n"
                             "######################################################################\n")

        output_results.write("avg test accuracy: " + str(avg_acc_lad_soft_votes) + "\n")
        output_results.write("standard deviation: " + str(std_value_lad_soft_votes) + "\n")
        output_results.write("avg total number of nodes in a forest: " + str(avg_nodes_lad_soft_votes) + "\n")
        output_results.write("avg total number of features used in a forest: " + str(avg_num_features_lad_soft_votes) + "\n")
        output_results.write("avg time for rf: " + str(avg_time_rf_lad_soft_votes) + "\n\n")
        output_results.write("avg time for generating 100000 MHSes: " + str(avg_time_MHSes_lad_soft_votes) + "\n")
        output_results.write("avg time for randomly selecting LAD subsets: " + str(avg_time_subsets_ranking_lad_soft_votes) + "\n")
        output_results.write("avg time for lad: " + str(avg_time_lad_soft_votes) + "\n")
        output_results.write("avg length subset for each tree before constructing: " + str(avg_length_subset_lad_soft_votes) + "\n")


        # delete all temporary files of LAD method
        change_directory_and_delete_all_input_and_output_hypergraph_files_for_binary_dataset_RF(
            dataset_name=dataset_name,
            max_depth=max_depth)
        print("Finished writing results...\n\n\n")
    print(f"After {k_fold} cross validations with {n_repeats} repetitions:")
    print(f"For dataset {dataset_name} using depth={max_depth}:\n")
    print("######################################################################\n"
          "#                      RF sklearn summary results                    #\n"
          "######################################################################")
    print("avg_test_accuracy: " + str(avg_acc_rf))
    print("standard deviation: " + str(std_value_rf))
    print("avg total number of nodes in a forest: " + str(avg_nodes_rf))
    print("avg total number of features used in a forest: " + str(avg_num_features_rf))
    print("avg_time: " + str(avg_time_rf) + "\n")
    print("######################################################################\n"
          f"#           RF using DTs generated by LAD with majority votes        #\n"
          "#######################################################################")
    print("avg test accuracy: " + str(avg_acc_lad_majority_votes))
    print("standard deviation: " + str(std_value_lad_majority_votes))
    print("avg total number of nodes in a forest: " + str(avg_nodes_lad_majority_votes))
    print("avg total number of features used in a forest: " + str(avg_num_features_lad_majority_votes))
    print("avg time for rf: " + str(avg_time_rf_lad_majority_votes))
    print("avg time for generating 100000 MHSes: " + str(avg_time_MHSes_lad_majority_votes))
    print("avg time for randomly selecting LAD subsets: " + str(avg_time_subsets_ranking_lad_majority_votes))
    print("avg time for lad: " + str(avg_time_lad_majority_votes))
    print("avg length subset for each tree before constructing: " + str(avg_length_subset_lad_majority_votes) + "\n")
    print("######################################################################\n"
          f"#           RF using DTs generated by LAD with soft votes           #\n"
          "######################################################################")
    print("avg test accuracy: " + str(avg_acc_lad_soft_votes))
    print("standard deviation: " + str(std_value_lad_soft_votes))
    print("avg total number of nodes in a forest: " + str(avg_nodes_lad_soft_votes))
    print("avg total number of features used in a forest: " + str(avg_num_features_lad_soft_votes))
    print("avg time for rf: " + str(avg_time_rf_lad_soft_votes))
